import { buildSchema, graphql } from "graphql";
const schema = buildSchema("input BookInput { title: String! } type Query { ready: Boolean! } type Mutation { createBook(book: BookInput!): String! }");

const rootValue = { ready: () => true, createBook: ({ book }) => book.title };
const result = await graphql({ schema, rootValue, source: "mutation { createBook(book: { title: \"Moon Trip\" }) }", variableValues: {} });
console.log(JSON.stringify(result.data));
